using Microsoft.EntityFrameworkCore; using CarServices.Data; using CarServices.Models; var builder=WebApplication.CreateBuilder(args); builder.Services.AddDbContext<AppDbContext>(o=>o.UseSqlServer(builder.Configuration.GetConnectionString("DefaultConnection"))); builder.Services.AddControllers(); builder.Services.AddCors(o=>o.AddDefaultPolicy(p=>p.AllowAnyOrigin().AllowAnyHeader().AllowAnyMethod())); var app=builder.Build(); app.UseCors(); app.MapControllers(); using(var s=app.Services.CreateScope()){var db=s.ServiceProvider.GetRequiredService<AppDbContext>(); db.Database.EnsureCreated(); if(!db.Services.Any()){db.Services.AddRange(new Service{Name="Oil Change",Description="Engine oil and filter service",Price=50},new Service{Name="Brake Service",Description="Brake inspection and maintenance",Price=100},new Service{Name="Full Car Wash",Description="Premium exterior and interior wash",Price=35});db.SaveChanges();}} app.Run();
